import Component from 'flarum/common/Component';
import classList from 'flarum/common/utils/classList';
import rankGroups from '../helpers/rankGroups';
import RankBanner from './RankBanner';
export default class RankBanners extends Component {
  view() {
    const groups = rankGroups(this.attrs.user);
    if (!groups.length) {
      return null;
    }
    return m("div", {
      className: classList('RankBanners', this.attrs.className)
    }, groups.map(group => m(RankBanner, {
      group: group,
      key: group.id()
    })));
  }
}
flarum.reg.add('prm-rank-banner', 'forum/components/RankBanners', RankBanners);